// Validation et préparation des données
const input = $input.first().json;
const body = input.body || input;

const startTime = Date.now();

// Extraction des paramètres
const text = body.text || '';
const apiKey = body.api_key || '';
const openaiApiKey = body.openai_api_key || '';
const targetLanguage = body.target_language || 'fr';
const sourceLanguage = body.source_language || 'auto';
const sourceTextId = body.source_text_id || null;
const commentaryId = body.commentary_id || null;
const context = body.context || {};
const discord = body.discord || {};

// Validation
const errors = [];
if (!text || text.trim().length === 0) {
  errors.push('Le champ "text" est requis');
}
if (!apiKey || apiKey.trim().length === 0) {
  errors.push('Le champ "api_key" (Anthropic) est requis');
}
if (!openaiApiKey || openaiApiKey.trim().length === 0) {
  errors.push('Le champ "openai_api_key" est requis');
}

// Mapping langues
const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen'
};

const targetLangName = languageNames[targetLanguage] || 'français';
const sourceLangName = sourceLanguage === 'auto' ? null : (languageNames[sourceLanguage] || sourceLanguage);

// Construction du contexte pour le prompt
let contextInfo = '';
if (context.traite || context.page || context.commentator) {
  contextInfo = `\n\nContexte: ${context.commentator || ''} sur ${context.traite || ''} ${context.page || ''}`.trim();
}

// Construire l'URL de recherche cache
let cacheSearchParams = `target_language=${targetLanguage}`;
if (sourceTextId) {
  cacheSearchParams += `&source_text_id=${sourceTextId}`;
} else if (commentaryId) {
  cacheSearchParams += `&commentary_id=${commentaryId}`;
} else if (context.traite && context.page) {
  cacheSearchParams += `&traite=${encodeURIComponent(context.traite)}&page=${encodeURIComponent(context.page)}`;
  if (context.commentator) {
    cacheSearchParams += `&commentator=${encodeURIComponent(context.commentator)}`;
  }
  cacheSearchParams += `&text=${encodeURIComponent(text)}&exact=true`;
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    text: text,
    apiKey: apiKey,
    openaiApiKey: openaiApiKey,
    targetLanguage: targetLanguage,
    targetLangName: targetLangName,
    sourceLanguage: sourceLanguage,
    sourceLangName: sourceLangName,
    sourceTextId: sourceTextId,
    commentaryId: commentaryId,
    contextInfo: contextInfo,
    context: context,
    discord: discord,
    startTime: startTime,
    cacheSearchParams: cacheSearchParams,
    canSearchCache: !!(sourceTextId || commentaryId || (context.traite && context.page))
  }
}];

// Vérifier si le cache a retourné une traduction
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Cache hit si status 200 et traduction trouvée
const cacheHit = statusCode === 200 && data.found === true && data.translations && data.translations.length > 0;

if (cacheHit) {
  const cached = data.translations[0];
  return [{
    json: {
      cacheHit: true,
      translation: cached.translated_text,
      qualityScore: cached.quality_score || 0.9,
      provider: cached.provider || 'cached',
      model: cached.model || 'cached',
      cachedAt: cached.created_at,
      // Passer les données pour la réponse
      originalText: prevData.text,
      targetLanguage: prevData.targetLanguage,
      context: prevData.context,
      discord: prevData.discord,
      startTime: prevData.startTime
    }
  }];
}

// Cache miss - passer au traducteur
return [{
  json: {
    cacheHit: false,
    ...prevData
  }
}];

// Formater la réponse depuis le cache
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    translation: {
      original: input.originalText,
      translated: input.translation,
      source_language: 'he',
      target_language: input.targetLanguage,
      quality_score: input.qualityScore
    },
    verification: {
      approved: true,
      confidence: input.qualityScore,
      issues: [],
      notes: 'Traduction depuis le cache'
    },
    alternatives: null,
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      models_used: [input.provider || 'cached'],
      source: 'cache',
      cached_at: input.cachedAt,
      processing_time_ms: processingTime
    },
    discord: input.discord
  }
}];

// Extraire la traduction Claude et préparer pour GPT-4o
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

// Gestion fullResponse ou réponse directe
const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier les erreurs HTTP Claude
// Claude retourne type='error' en cas d'erreur, ou un objet error avec message
const hasClaudeError = statusCode >= 400 || data.type === 'error' || (data.error && data.error.message);
if (hasClaudeError) {
  const errorMsg = data.error?.message || data.message || `Erreur HTTP ${statusCode}`;
  const errorType = data.error?.type || data.type || 'unknown';
  return [{
    json: {
      success: false,
      error: {
        code: statusCode >= 400 ? statusCode : 401,
        message: `Erreur API Claude: ${errorMsg}`,
        status: 'CLAUDE_API_ERROR',
        debug: { errorType: errorType, statusCode: statusCode }
      }
    }
  }];
}

// Extraire la traduction de Claude
let claudeTranslation = '';
if (data.content && data.content[0] && data.content[0].text) {
  claudeTranslation = data.content[0].text.trim();
}

if (!claudeTranslation) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Aucune traduction retournée par Claude',
        status: 'EMPTY_CLAUDE_RESPONSE',
        debug: { statusCode: statusCode, hasContent: !!data.content, keys: Object.keys(data) }
      }
    }
  }];
}

// Préparer les données pour GPT-4o
return [{
  json: {
    claudeTranslation: claudeTranslation,
    originalText: prevData.text,
    targetLanguage: prevData.targetLanguage,
    targetLangName: prevData.targetLangName,
    sourceLanguage: prevData.sourceLanguage,
    sourceTextId: prevData.sourceTextId,
    commentaryId: prevData.commentaryId,
    context: prevData.context,
    contextInfo: prevData.contextInfo,
    openaiApiKey: prevData.openaiApiKey,
    discord: prevData.discord,
    startTime: prevData.startTime,
    claudeUsage: {
      input_tokens: data.usage?.input_tokens || 0,
      output_tokens: data.usage?.output_tokens || 0
    }
  }
}];

// Formater et préparer sauvegarde en BDD
const gptResponse = $input.first().json;
const claudeData = $('Extract Claude Response').first().json;

const endTime = Date.now();
const processingTime = endTime - claudeData.startTime;

// Parser la réponse GPT-4o
const gptData = gptResponse.body || gptResponse;
const gptStatusCode = gptResponse.statusCode || 200;

// Valeurs par défaut si GPT-4o échoue
let verification = {
  approved: true,
  confidence: 0.7,
  corrected_translation: null,
  issues: [],
  notes: 'Vérification GPT-4o non disponible'
};

let gptUsage = { prompt_tokens: 0, completion_tokens: 0 };
let verifierError = null;

// Debug info
const gptDebug = {
  statusCode: gptStatusCode,
  responseKeys: Object.keys(gptData || {}),
  hasChoices: !!(gptData.choices && gptData.choices.length > 0),
  apiKeyProvided: !!claudeData.openaiApiKey,
  apiKeyLen: claudeData.openaiApiKey ? claudeData.openaiApiKey.length : 0,
  apiKeyPrefix: claudeData.openaiApiKey ? claudeData.openaiApiKey.substring(0, 7) + '...' : 'MISSING'
};

if (gptStatusCode >= 400 || gptData.error) {
  verifierError = gptData.error?.message || gptData.error?.code || `HTTP ${gptStatusCode}`;
  gptDebug.rawError = JSON.stringify(gptData.error || gptData).substring(0, 500);
} else if (gptData.choices && gptData.choices[0]?.message?.content) {
  try {
    verification = JSON.parse(gptData.choices[0].message.content);
    gptUsage = gptData.usage || gptUsage;
  } catch (e) {
    verifierError = 'Erreur parsing JSON: ' + e.message;
    gptDebug.rawContent = gptData.choices[0].message.content.substring(0, 200);
  }
} else {
  verifierError = 'Réponse GPT-4o invalide';
  gptDebug.rawResponse = JSON.stringify(gptData).substring(0, 300);
}

// Déterminer la traduction finale
const hasSignificantDisagreement = !verification.approved && verification.confidence < 0.6;
const finalTranslation = verification.corrected_translation || claudeData.claudeTranslation;

// Construire la réponse
const response = {
  success: true,
  cached: false,
  translation: {
    original: claudeData.originalText,
    translated: finalTranslation,
    source_language: claudeData.sourceLanguage || 'auto',
    target_language: claudeData.targetLanguage,
    quality_score: verification.confidence
  },
  verification: {
    approved: verification.approved,
    confidence: verification.confidence,
    issues: verification.issues || [],
    notes: verification.notes || null,
    verifier_error: verifierError,
    debug: gptDebug
  },
  alternatives: hasSignificantDisagreement ? {
    claude_translation: claudeData.claudeTranslation,
    gpt4o_translation: verification.corrected_translation
  } : null,
  metadata: {
    traite: claudeData.context.traite || null,
    page: claudeData.context.page || null,
    commentator: claudeData.context.commentator || null,
    source_text_id: claudeData.sourceTextId || null,
    commentary_id: claudeData.commentaryId || null,
    models_used: ['claude-sonnet-4-20250514', 'gpt-4o'],
    source: 'generated',
    processing_time_ms: processingTime,
    tokens: {
      claude: claudeData.claudeUsage,
      gpt4o: gptUsage
    }
  },
  discord: claudeData.discord,
  // Données pour sauvegarde
  _saveData: {
    text: claudeData.originalText,
    translated_text: finalTranslation,
    source_text_id: claudeData.sourceTextId,
    commentary_id: claudeData.commentaryId,
    traite: claudeData.context.traite,
    page: claudeData.context.page,
    commentator: claudeData.context.commentator,
    source_language: claudeData.sourceLanguage || 'auto',
    target_language: claudeData.targetLanguage,
    quality_score: verification.confidence,
    provider: 'claude+gpt4o',
    model: 'claude-sonnet-4+gpt-4o'
  }
};

return [{ json: response }];

// Nettoyer la réponse (supprimer _saveData)
const input = $input.first().json;
const prevResponse = $('Format Final Response').first().json;

// Supprimer les données internes
const response = { ...prevResponse };
delete response._saveData;

return [{ json: response }];

