    "title": "Traduction {{ $json.metadata.commentator ? $json.metadata.commentator + ' - ' : '' }}{{ $json.metadata.traite || '' }} {{ $json.metadata.page || '' }}",
    "color": {{ $json.cached ? 3447003 : ($json.verification.approved ? 5763719 : 15548997) }},
    "fields": [
      {
        "name": "Original (he)",
        "value": "{{ $json.translation.original.substring(0, 500) }}{{ $json.translation.original.length > 500 ? '...' : '' }}",
        "inline": false
      },
      {
        "name": "Traduction ({{ $json.translation.target_language }})",
        "value": "{{ $json.translation.translated.substring(0, 900) }}{{ $json.translation.translated.length > 900 ? '...' : '' }}",
        "inline": false
      },
      {
        "name": "Score",
        "value": "{{ Math.round($json.translation.quality_score * 100) }}%",
        "inline": true
      },
      {
        "name": "Source",
        "value": "{{ $json.cached ? '📦 Cache' : ($json.verification.approved ? '✅ Vérifié' : '⚠️ Corrigé') }}",
        "inline": true
      },
      {
        "name": "Temps",
        "value": "{{ Math.round($json.metadata.processing_time_ms / 1000 * 10) / 10 }}s",
        "inline": true
      }
    ],
    "footer": { "text": "{{ $json.cached ? 'Cache Torah API' : 'Claude Sonnet 4 + GPT-4o' }}" },
    "timestamp": "{{ new Date().toISOString() }}"
  }]
}

